let lang = 'pl';
let activeProject = null;
const menuButton = document.querySelector('.menu-toggle');
const menu = document.querySelector('#mobile-menu');
const projectDialog = document.querySelector('#project-dialog');
const briefDialog = document.querySelector('#brief-dialog');
const t = key => translations[lang][key];
function renderProject() {
  if (activeProject === null) return;
  const index = activeProject + 1;
  document.querySelector('#dialog-title').textContent = t(`project${index}`);
  document.querySelector('#dialog-desc').textContent = t(`project${index}Desc`);
  const image = document.querySelector('#dialog-image');
  image.src = activeProject === 0 ? 'assets/meadow.jpg' : 'assets/courtyard.jpg';
  image.alt = t(activeProject === 0 ? 'meadowAlt' : 'courtyardAlt');
}
function setLanguage(next, persist = true) {
  lang = next in translations ? next : 'pl';
  document.documentElement.lang = lang;
  document.title = t('title');
  document.querySelector('meta[name="description"]').content = t('meta');
  document.querySelectorAll('[data-i18n]').forEach(el => { el.innerHTML = t(el.dataset.i18n); });
  document.querySelectorAll('[data-alt]').forEach(el => { el.alt = t(el.dataset.alt); });
  document.querySelectorAll('[data-placeholder]').forEach(el => { el.placeholder = t(el.dataset.placeholder); });
  document.querySelectorAll('[data-lang]').forEach(el => { el.setAttribute('aria-pressed', String(el.dataset.lang === lang)); });
  document.querySelectorAll('[data-close]').forEach(el => { el.setAttribute('aria-label', t('close')); });
  document.querySelector('#open-brief').setAttribute('aria-label', t('briefCta'));
  menuButton.setAttribute('aria-label', t(menu.hidden ? 'menuOpen' : 'menuClose'));
  document.querySelector('.form-status').textContent = '';
  renderProject();
  if (persist) { try { localStorage.setItem('terren-language', lang); } catch {} }
}
document.querySelectorAll('[data-lang]').forEach(button => button.addEventListener('click', () => setLanguage(button.dataset.lang)));
function closeMenu() { menu.hidden = true; menuButton.setAttribute('aria-expanded', 'false'); menuButton.setAttribute('aria-label', t('menuOpen')); }
menuButton.addEventListener('click', () => { menu.hidden = !menu.hidden; menuButton.setAttribute('aria-expanded', String(!menu.hidden)); menuButton.setAttribute('aria-label', t(menu.hidden ? 'menuOpen' : 'menuClose')); });
menu.querySelectorAll('a').forEach(link => link.addEventListener('click', closeMenu));
document.addEventListener('keydown', event => { if (event.key === 'Escape') closeMenu(); });
function openDialog(dialog) { closeMenu(); dialog.showModal(); document.body.style.overflow = 'hidden'; }
document.querySelectorAll('[data-project]').forEach(button => button.addEventListener('click', () => { activeProject = Number(button.dataset.project); renderProject(); openDialog(projectDialog); }));
['open-brief', 'brief-link'].forEach(id => document.getElementById(id).addEventListener('click', () => openDialog(briefDialog)));
document.querySelectorAll('dialog').forEach(dialog => {
  dialog.querySelector('[data-close]').addEventListener('click', () => dialog.close());
  dialog.addEventListener('close', () => { document.body.style.overflow = ''; });
  dialog.addEventListener('click', event => { if (event.target !== dialog) return; const rect = dialog.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) dialog.close(); });
});
document.querySelector('#brief-form').addEventListener('submit', event => {
  event.preventDefault();
  const form = new FormData(event.currentTarget);
  const brief = `TERREN — ${t('briefCta')}\n\n${t('formPlace')}\n${form.get('place')}\n\n${t('formArea')}\n${form.get('area') || '—'}\n\n${t('formDream')}\n${form.get('dream')}\n`;
  const url = URL.createObjectURL(new Blob(['\uFEFF', brief], { type: 'text/plain;charset=utf-8' }));
  const link = document.createElement('a'); link.href = url; link.download = `TERREN-brief-${lang}.txt`; document.body.append(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000);
  document.querySelector('.form-status').textContent = t('saved');
});
try { const saved = localStorage.getItem('terren-language'); setLanguage(saved || 'pl', false); } catch { setLanguage('pl', false); }
document.querySelector('#year').textContent = new Date().getFullYear();

